import React from 'react';
import { placeOrder } from '../services/api';
import { useNavigate } from 'react-router-dom';

function CartPage({ cart, onClearCart }) {
    const navigate = useNavigate();

    const handlePlaceOrder = async () => {
        try {
            const products = cart.map((item) => ({
                product: item.id,
                quantity: item.quantity,
                price: item.price,
            }));
            const totalAmount = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);

            const orderData = await placeOrder({ products, totalAmount });
            onClearCart(); // Clear the cart after successful order
            alert('Order placed successfully!');
            navigate('/orders'); // Redirect to orders page
        } catch (error) {
            alert('Failed to place order: ' + error.message);
        }
    };

    return (
        <div className="cart-page">
            <h1>Your Cart</h1>
            {cart.length === 0 ? (
                <p>Your cart is empty.</p>
            ) : (
                <>
                    <ul>
                        {cart.map((item) => (
                            <li key={item.id}>
                                {item.name} - ${item.price} (x{item.quantity})
                            </li>
                        ))}
                    </ul>
                    <h2>Total: ${cart.reduce((sum, item) => sum + item.price * item.quantity, 0).toFixed(2)}</h2>
                    <button onClick={handlePlaceOrder} className="place-order-button">
                        Place Order
                    </button>
                </>
            )}
        </div>
    );
}

export default CartPage;
